"""Turn model interleavings into deterministic tests, and check real calls against the spec."""
import threading
from concurrent.futures import ThreadPoolExecutor

from snappea import check_events

from wallet import Store, Wallet


class SameVersionStore:
    """Real store; the first two loads wait for each other, so both callers read the
    same version before either writes. One compare-and-swap must then fail."""

    def __init__(self, inner):
        self.inner, self.barrier, self.waiting = inner, threading.Barrier(2, timeout=2), 2
        self.lock = threading.Lock()

    def load(self):
        result = self.inner.load()
        with self.lock:
            wait, self.waiting = self.waiting > 0, self.waiting - 1
        if wait:
            self.barrier.wait()
        return result

    def compare_swap(self, version, value):
        return self.inner.compare_swap(version, value)


class InterferingStore:
    """Real store that runs `competitor` once, between this caller's load and its
    compare-and-swap. The competitor uses the inner store, so it is not interrupted."""

    def __init__(self, inner, competitor):
        self.inner, self.competitor = inner, competitor

    def load(self):
        result = self.inner.load()
        if self.competitor:
            run, self.competitor = self.competitor, None
            run()
        return result

    def compare_swap(self, version, value):
        return self.inner.compare_swap(version, value)


class Recorder:
    """Wraps real calls; records actual arguments and results as spec events."""

/*
 * File map (search these names):
 * Capacity = oracle; Store/Client = correct conditional write;
 * StaleStore/StaleClient = defective split read/write; test tc* = selections;
 * storage.py/test_storage.py = real implementation and saved capture tests.
 *
 * Reservation: distinguish an atomic conditional write from stale read/check/write.
 *
 * Contract: committed reservations never exceed initial stock; Python tests also
 * compare actual remaining stock and reservation records. Capacity subtracts
 * positive committed effects independently, rejects duplicate order IDs, and
 * stays hot after opening until the first reservation, requiring useful work.
 * It does not trust an implementation-valid flag.
 *
 * Correct Store check/update is one atomic storage primitive. Broken StaleStore
 * separates read from unconditional write: both clients may read the last unit,
 * then each reserve it. Locking only final writes still oversells/loses a decrement.
 * The real implementation needs a transaction, conditional update, or one lock
 * covering validation + stock + reservation. This is NOT a client-side CAS loop;
 * see ../cas-retry/Balance.p for candidates, failed CAS, reload and recomputation.
 *
 * Run from this directory:
